1	//! Configuration and secret-file handling for the media broker.
2	//!
3	//! Write tools are opt-in: requests enable brokered adds, monitoring changes,
4	//! and search triggers, deletes enable the two-phase destructive media
5	//! removal tool, and reseeds enable the verified-complete qBittorrent reseed
6	//! into allow-listed save paths. Every upstream is optional, but at least one
7	//! must be set.
8	
9	use std::{
10	    collections::HashMap, fmt, fs, os::unix::fs::PermissionsExt, str::FromStr, time::Duration,
11	};
12	
13	use url::Url;
14	
15	/// Required broker configuration is absent or unsafe.
16	#[derive(Debug)]
17	pub struct ConfigError(String);
18	
19	impl fmt::Display for ConfigError {
20	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
21	        f.write_str(&self.0)
22	    }
23	}
24	
25	impl std::error::Error for ConfigError {}
26	
27	type Result<T> = std::result::Result<T, ConfigError>;
28	
29	macro_rules! bail {
30	    ($($message:tt)*) => { return Err(ConfigError(format!($($message)*))) };
31	}
32	
33	/// A credential that never appears in `Debug` output.
34	#[derive(Clone)]
35	pub struct REDACTED(String);
36	
37	impl REDACTED {
38	    pub fn new(value: impl Into<String>) -> Self {
39	        Self(value.into())
40	    }
41	
42	    #[must_use]
43	    pub fn expose(&self) -> &str {
44	        &self.0
45	    }
46	}
47	
48	impl fmt::Debug for REDACTED {
49	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
50	        f.write_str("<redacted>")
51	    }
52	}
53	
54	/// The six allow-listed upstream APIs.
55	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
56	pub enum Service {
57	    Sonarr,
58	    Radarr,
59	    Lidarr,
60	    Tautulli,
61	    Jellyfin,
62	    Qbittorrent,
63	}
64	
65	/// One row per [`Service`], in declaration order: name, API root.
66	const SERVICES: [[&str; 2]; 6] = [
67	    ["sonarr", "/api/v3"],
68	    ["radarr", "/api/v3"],
69	    ["lidarr", "/api/v1"],
70	    ["tautulli", "/api/v2"],
71	    ["jellyfin", ""],
72	    ["qbittorrent", "/api/v2"],
73	];
74	
75	impl Service {
76	    pub const ALL: [Self; 6] = [
77	        Self::Sonarr,
78	        Self::Radarr,
79	        Self::Lidarr,
80	        Self::Tautulli,
81	        Self::Jellyfin,
82	        Self::Qbittorrent,
83	    ];
84	
85	    #[must_use]
86	    pub const fn name(self) -> &'static str {
87	        SERVICES[self as usize][0]
88	    }
89	
90	    /// The pinned API version prefix under the base URL.
91	    #[must_use]
92	    pub const fn api_root(self) -> &'static str {
93	        SERVICES[self as usize][1]
94	    }
95	
96	    /// The header that carries the API key; keys never travel in URLs.
97	    /// qBittorrent authenticates with a session cookie instead.
98	    #[must_use]
99	    pub const fn key_header(self) -> Option<&'static str> {
100	        match self {
101	            Self::Sonarr | Self::Radarr | Self::Lidarr | Self::Tautulli => Some("X-Api-Key"),
102	            Self::Jellyfin => Some("X-Emby-Token"),
103	            Self::Qbittorrent => None,
104	        }
105	    }
106	}
107	
108	/// How the broker authenticates to one upstream.
109	#[derive(Clone, Debug)]
110	pub enum Auth {
111	    /// A static API key sent in the service's key header.
112	    Key(REDACTED),
113	    /// `WebUI` session credentials; the broker logs in and holds the cookie.
114	    Session { username: String, password: REDACTED },
115	}
116	
117	#[derive(Clone, Debug)]
118	pub struct Upstream {
119	    pub base_url: String,
120	    pub auth: Auth,
121	}
122	
123	/// Fully loaded settings.
124	#[derive(Clone, Debug)]
125	pub struct Settings {
126	    pub bearer_token: REDACTED,
127	    /// Indexed by `Service`; read through [`Settings::upstream`].
128	    pub upstreams: [Option<Upstream>; 6],
129	    pub allowed_hosts: Vec<String>,
130	    pub allowed_origins: Vec<String>,
131	    pub bind_host: String,
132	    pub port: u16,
133	    /// Total deadline for one upstream exchange.
134	    pub timeout: Duration,
135	    pub max_response_bytes: usize,
136	    pub enable_requests: bool,
137	    pub enable_deletes: bool,
138	    pub enable_reseeds: bool,
139	    /// Exact qBittorrent save paths a reseed may target; empty unless enabled.
140	    pub reseed_save_paths: Vec<String>,
141	    /// Lifetime of a delete confirmation.
142	    pub confirmation_ttl: Duration,
143	    /// How often a reseed polls qBittorrent while a recheck runs.
144	    pub reseed_poll_interval: Duration,
145	    /// Total time one reseed call may wait for the torrent and its recheck;
146	    /// a longer check reports `checking` and resumes on replay.
147	    pub reseed_deadline: Duration,
148	}
149	
150	type Env = HashMap<String, String>;
151	
152	#[derive(Clone, Copy)]
153	enum Exact {
154	    Endpoint,
155	    Host,
156	    Origin,
157	}
158	
159	fn required<'a>(env: &'a Env, name: &str) -> Result<&'a str> {
160	    match env.get(name).map(|value| value.trim()) {
161	        Some(value) if !value.is_empty() => Ok(value),
162	        _ => bail!("missing required configuration: {name}"),
163	    }
164	}
165	
166	/// Read the secret file named by a variable, never logging it.
167	fn secret(env: &Env, name: &str) -> Result<REDACTED> {
168	    let path = required(env, name)?;
169	    let Some(file) = fs::metadata(path).ok().filter(fs::Metadata::is_file) else {
170	        bail!("{name} must name a regular secret file");
171	    };
172	    if file.permissions().mode() & 0o007 != 0 {
173	        bail!("{name} must not be world-readable");
174	    }
175	    let Ok(content) = fs::read_to_string(path) else { bail!("unable to read {name}") };
176	    let value = content.trim();
177	    if value.is_empty() || value.chars().count() > 4096 {
178	        bail!("{name} is empty or too large");
179	    }
180	    Ok(REDACTED::new(value))
181	}
182	
183	/// Validate one exact URL or authority: no wildcards, credentials, query,
184	/// fragment, or bad port; only an endpoint may carry a path.
185	fn exact(name: &str, value: &str, kind: Exact) -> Result<String> {
186	    let (scheme, rest) = match value.split_once("://") {
187	        Some((scheme, rest)) => (Some(scheme), rest),
188	        None => (None, value),
189	    };
190	    let (expected, scheme_fits, path_fits) = match kind {
191	        Exact::Endpoint => ("http(s) URL", scheme.is_some(), true),
192	        Exact::Host => ("Host authority", scheme.is_none(), !rest.contains('/')),
193	        Exact::Origin => ("Origin", scheme.is_some(), !rest.contains('/')),
194	    };
195	    let well_formed = scheme.is_none_or(|scheme| matches!(scheme, "http" | "https"))
196	        && !value.contains(|character: char| character == '*' || character.is_whitespace())
197	        && Url::parse(&format!("http://{rest}")).is_ok_and(|url| {
198	            url.username().is_empty()
199	                && url.password().is_none()
200	                && url.query().is_none()
201	                && url.fragment().is_none()
202	        });
203	    if !(scheme_fits && path_fits && well_formed) {
204	        bail!("invalid {name}: expected an exact {expected}");
205	    }
206	    Ok(value.trim_end_matches('/').to_owned())
207	}
208	
209	/// Parse an explicit boolean; never guess on typos.
210	fn flag(env: &Env, name: &str) -> Result<bool> {
211	    match env.get(name).map_or("false", |raw| raw.trim()) {
212	        raw if raw.eq_ignore_ascii_case("true") => Ok(true),
213	        raw if raw.eq_ignore_ascii_case("false") => Ok(false),
214	        _ => bail!("{name} must be true or false"),
215	    }
216	}
217	
218	fn number<N>(env: &Env, name: &str, default: N, low: N, high: N) -> Result<N>
219	where
220	    N: Copy + FromStr + PartialOrd + fmt::Display,
221	{
222	    let value = match env.get(name).map(|raw| raw.trim().parse()) {
223	        Some(Ok(value)) => value,
224	        Some(Err(_)) => bail!("{name} must be a number"),
225	        None => default,
226	    };
227	    if !(low..=high).contains(&value) {
228	        bail!("{name} must be between {low} and {high}");
229	    }
230	    Ok(value)
231	}
232	
233	fn csv(env: &Env, name: &str, default: Option<String>, kind: Exact) -> Result<Vec<String>> {
234	    let raw = match (env.get(name), default) {
235	        (None, Some(default)) => default,
236	        (raw, _) => raw.cloned().unwrap_or_default(),
237	    };
238	    let values: Vec<&str> =
239	        raw.split(',').map(str::trim).filter(|value| !value.is_empty()).collect();
240	    if values.is_empty() {
241	        bail!("{name} must contain at least one value");
242	    }
243	    values.iter().map(|value| exact(name, value, kind)).collect()
244	}
245	
246	/// Exact absolute directories without dot segments, wildcards, or control
247	/// characters; the filesystem root is refused because it allows everything.
248	fn save_paths(env: &Env, enabled: bool) -> Result<Vec<String>> {
249	    const NAME: &str = "QBITTORRENT_RESEED_SAVE_PATHS";
250	    let raw = env.get(NAME).map_or("", |raw| raw.trim());
251	    if !enabled {
252	        if !raw.is_empty() {
253	            bail!("{NAME} requires MEDIA_BROKER_ENABLE_RESEEDS=true");
254	        }
255	        return Ok(Vec::new());
256	    }
257	    let paths: Vec<&str> = raw.split(',').map(str::trim).filter(|path| !path.is_empty()).collect();
258	    if paths.is_empty() {
259	        bail!("{NAME} must contain at least one value when reseeds are enabled");
260	    }
261	    let exact_path = |path: &&str| {
262	        let segments = path.trim_end_matches('/').split('/').skip(1);
263	        path.starts_with('/')
264	            && path.trim_end_matches('/').len() > 1
265	            && !path.contains(|character: char| character == '*' || character.is_control())
266	            && segments.clone().all(|segment| !matches!(segment, "" | "." | ".."))
267	    };
268	    if let Some(path) = paths.iter().find(|path| !exact_path(path)) {
269	        bail!("invalid {NAME}: {path} is not an exact absolute directory");
270	    }
271	    Ok(paths.iter().map(|path| path.trim_end_matches('/').to_owned()).collect())
272	}
273	
274	/// Load one optional upstream; a credential without a URL is an error, and
275	/// inline credentials are forbidden.
276	fn upstream(env: &Env, service: Service) -> Result<Option<Upstream>> {
277	    let prefix = service.name().to_uppercase();
278	    let url_name = format!("{prefix}_URL");
279	    let url = env.get(&url_name).map_or("", |value| value.trim());
280	    if service == Service::Qbittorrent {
281	        if env.get("QBITTORRENT_PASSWORD").is_some_and(|value| !value.is_empty()) {
282	            bail!("the qBittorrent password must be set with QBITTORRENT_PASSWORD_FILE");
283	        }
284	        if url.is_empty() {
285	            let set = |name: &str| env.get(name).is_some_and(|value| !value.trim().is_empty());
286	            if set("QBITTORRENT_USERNAME") || set("QBITTORRENT_PASSWORD_FILE") {
287	                bail!("QBITTORRENT_URL is required when its credentials are set");
288	            }
289	            return Ok(None);
290	        }
291	        return Ok(Some(Upstream {
292	            base_url: exact(&url_name, url, Exact::Endpoint)?,
293	            auth: Auth::Session {
294	                username: required(env, "QBITTORRENT_USERNAME")?.to_owned(),
295	                password: secret(env, "QBITTORRENT_PASSWORD_FILE")?,
296	            },
297	        }));
298	    }
299	    if env.get(&format!("{prefix}_API_KEY")).is_some_and(|key| !key.is_empty()) {
300	        bail!("upstream API keys must be configured with *_API_KEY_FILE");
301	    }
302	    let key_file = format!("{prefix}_API_KEY_FILE");
303	    if url.is_empty() {
304	        if env.get(&key_file).is_some_and(|value| !value.trim().is_empty()) {
305	            bail!("{url_name} is required when {key_file} is set");
306	        }
307	        return Ok(None);
308	    }
309	    Ok(Some(Upstream {
310	        base_url: exact(&url_name, url, Exact::Endpoint)?,
311	        auth: Auth::Key(secret(env, &key_file)?),
312	    }))
313	}
314	
315	impl Settings {
316	    #[must_use]
317	    pub fn upstream(&self, service: Service) -> Option<&Upstream> {
318	        self.upstreams[service as usize].as_ref()
319	    }
320	
321	    /// Load all values from the given environment and the secret files it names.
322	    ///
323	    /// # Errors
324	    /// Returns the first absent or unsafe value, naming its variable.
325	    pub fn load(env: &Env) -> Result<Self> {
326	        let bind_host = env.get("MEDIA_BROKER_BIND_HOST").map_or("127.0.0.1", |host| host.trim());
327	        let public = bind_host == "0.0.0.0";
328	        if !public && !matches!(bind_host, "127.0.0.1" | "::1" | "localhost") {
329	            bail!("MEDIA_BROKER_BIND_HOST must be loopback or 0.0.0.0");
330	        }
331	        if flag(env, "MEDIA_BROKER_ALLOW_PUBLIC_BIND")? != public {
332	            bail!("MEDIA_BROKER_ALLOW_PUBLIC_BIND=true is required for 0.0.0.0 only");
333	        }
334	        let port = number(env, "MEDIA_BROKER_PORT", 8000, 1, u32::from(u16::MAX))?;
335	        // Loopback binding defaults to its own exact authority; public binding has
336	        // no safe implicit authority, so both allow-lists must be supplied.
337	        let authority = match bind_host {
338	            _ if public => None,
339	            host if host.contains(':') => Some(format!("[{host}]:{port}")),
340	            host => Some(format!("{host}:{port}")),
341	        };
342	        let bearer_token = secret(env, "MEDIA_BROKER_TOKEN_FILE")?;
343	        let token = bearer_token.expose();
344	        let url_safe = |byte: u8| byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'-';
345	        if !(32..=256).contains(&token.len()) || !token.bytes().all(url_safe) {
346	            bail!("MEDIA_BROKER_TOKEN_FILE must contain 32-256 URL-safe characters");
347	        }
348	        let timeout = number(env, "MEDIA_BROKER_TIMEOUT_SECONDS", 10.0, 0.1, 60.0)?;
349	        let [sonarr, radarr, lidarr, tautulli, jellyfin, qbittorrent] =
350	            Service::ALL.map(|service| upstream(env, service));
351	        let upstreams = [sonarr?, radarr?, lidarr?, tautulli?, jellyfin?, qbittorrent?];
352	        if upstreams.iter().all(Option::is_none) {
353	            bail!("at least one upstream must be configured");
354	        }
355	        let origin = authority.as_ref().map(|authority| format!("http://{authority}"));
356	        let enable_reseeds = flag(env, "MEDIA_BROKER_ENABLE_RESEEDS")?;
357	        if enable_reseeds && upstreams[Service::Qbittorrent as usize].is_none() {
358	            bail!("MEDIA_BROKER_ENABLE_RESEEDS=true requires QBITTORRENT_URL");
359	        }
360	        Ok(Self {
361	            bearer_token,
362	            upstreams,
363	            allowed_hosts: csv(env, "MEDIA_BROKER_ALLOWED_HOSTS", authority, Exact::Host)?,
364	            allowed_origins: csv(env, "MEDIA_BROKER_ALLOWED_ORIGINS", origin, Exact::Origin)?,
365	            bind_host: bind_host.to_owned(),
366	            port: u16::try_from(port).unwrap_or(u16::MAX), // range-checked above
367	            timeout: Duration::from_secs_f64(timeout),
368	            max_response_bytes: number(
369	                env,
370	                "MEDIA_BROKER_MAX_RESPONSE_BYTES",
371	                2_000_000,
372	                1_000,
373	                50_000_000,
374	            )?,
375	            enable_requests: flag(env, "MEDIA_BROKER_ENABLE_REQUESTS")?,
376	            enable_deletes: flag(env, "MEDIA_BROKER_ENABLE_DELETES")?,
377	            enable_reseeds,
378	            reseed_save_paths: save_paths(env, enable_reseeds)?,
379	            confirmation_ttl: Duration::from_secs(300),
380	            reseed_poll_interval: Duration::from_secs(1),
381	            reseed_deadline: Duration::from_secs(45),
382	        })
383	    }
384	}
