301	fn sonarr_seasons(candidate: &Value, selection: Option<&[u32]>) -> Result<Vec<Value>> {
302	    let rows = candidate["seasons"].as_array().into_iter().flatten();
303	    let numbers: Vec<i64> = rows.filter_map(|row| row["seasonNumber"].as_i64()).collect();
304	    if numbers.is_empty() {
305	        return parameter("the lookup candidate has no season metadata");
306	    }
307	    let wanted = selection.map(|seasons| seasons.iter().map(|season| i64::from(*season)));
308	    let wanted: Option<Vec<i64>> = wanted.map(Iterator::collect);
309	    if wanted.iter().flatten().any(|season| !numbers.contains(season)) {
310	        return parameter("one or more seasons do not exist on the candidate");
311	    }
312	    let selected = |number: &i64| wanted.as_ref().is_none_or(|wanted| wanted.contains(number));
313	    let season = |number: &i64| json!({"seasonNumber": number, "monitored": selected(number)});
314	    Ok(numbers.iter().map(season).collect())
