362	        method: Method,
363	        path: &str,
364	    ) -> Result<RequestBuilder> {
365	        let service = service.into();
366	        let Some(upstream) = self.settings.upstream(service) else {
367	            return parameter(format!("{} is not configured on this broker", service.name()));
368	        };
369	        let url = format!("{}{}{path}", upstream.base_url, service.api_root());
370	        let request = self.http.request(method, url);
371	        Ok(match &upstream.auth {
372	            Auth::Key(key) => {
373	                let header = service.key_header().expect("key auth names a header");
374	                request.header(header, key.expose())
375	            }
376	            // Session auth attaches its cookie inside the qBittorrent exchange.
377	            Auth::Session { .. } => request,
378	        })
379	    }
