381	    /// Send one request under a total deadline, returning the status and a
382	    /// size-capped body without judging the status.
383	    async fn exchange(&self, request: RequestBuilder) -> Result<(u16, Vec<u8>)> {
384	        let limit = self.settings.max_response_bytes;
385	        let exchange = async {
386	            let Ok(mut response) = request.send().await else {
387	                return upstream(FAILED);
388	            };
389	            let status = response.status().as_u16();
390	            if response.content_length().unwrap_or(0) > limit as u64 {
391	                return upstream(OVERSIZED);
392	            }
393	            let mut body = Vec::new();
394	            while let Some(chunk) = response.chunk().await.or_else(|_| upstream(FAILED))? {
395	                body.extend_from_slice(&chunk);
396	                if body.len() > limit {
397	                    return upstream(OVERSIZED);
398	                }
399	            }
400	            Ok((status, body))
401	        };
402	        let deadline = tokio::time::timeout(self.settings.timeout, exchange);
403	        deadline.await.unwrap_or_else(|_| upstream("upstream request timed out"))
404	    }
405	
406	    /// One exchange that rejects any HTTP error status.
407	    async fn fetch(&self, request: RequestBuilder) -> Result<Vec<u8>> {
408	        let (status, body) = self.exchange(request).await?;
409	        if status >= 300 {
410	            return upstream(format!("upstream returned HTTP {status}"));
411	        }
412	        Ok(body)
413	    }
