429	    /// Fetch a bounded list of upstream objects, dropping anything else.
430	    async fn rows(
431	        &self,
432	        service: impl Into<Service>,
433	        path: &str,
434	        query: &[(&str, String)],
435	    ) -> Result<Vec<Value>> {
436	        let request = self.request(service, Method::GET, path)?.query(query);
437	        match self.json(request).await? {
438	            Value::Array(rows) if rows.len() <= MAX_ITEMS => {
439	                Ok(rows.into_iter().filter(Value::is_object).collect())
440	            }
441	            _ => {
442	                let resource = path.split('/').nth(1).unwrap_or_default().to_lowercase();
443	                upstream(format!("upstream returned an unexpected {resource} response"))
444	            }
445	        }
446	    }
