451	        if content.len() > MAX_REQUEST_BYTES {
452	            return parameter("request payload exceeds the broker limit");
453	        }
454	        let request = self.request(service, method, path)?.body(content);
455	        self.record(request.header(CONTENT_TYPE, "application/json")).await
456	    }
