533	    /// Add one exact catalog item; the broker builds the add body itself.
534	    pub async fn request_media(
535	        &self,
536	        service: ArrService,
537	        external_id: &str,
538	        quality_profile_id: u32,
539	        root_folder_path: &str,
540	        search_on_add: bool,
541	        seasons: Option<&[u32]>,
542	    ) -> Result {
543	        let spec = service.spec();
544	        if seasons.is_some() && service != ArrService::Sonarr {
545	            return parameter("seasons is only supported for sonarr");
546	        }
547	        let identifier = external_id.trim();
548	        if !service.id_valid(identifier) {
549	            let (expected, name) = (spec.id_description, Service::from(service).name());
550	            return parameter(format!("external_id must be {expected} for {name}"));
551	        }
552	        let rows = self.lookup(service, format!("{}{identifier}", spec.lookup_prefix)).await?;
553	        let matches = |row: &&Value| {
554	            let external = &row[spec.external_field];
555	            let number = external.as_i64().map(|id| id.to_string());
556	            let found = number.or_else(|| text(external).map(str::to_owned));
557	            found.is_some_and(|found| found.eq_ignore_ascii_case(identifier))
558	        };
559	        let Some(candidate) = rows.iter().find(matches) else {
560	            return parameter("no upstream candidate matches the external identifier");
561	        };
562	        if candidate["id"].as_i64().is_some_and(|id| id != 0) {
563	            return parameter("the requested media is already in the library");
564	        }
565	        let root = self.add_destination(service, quality_profile_id, root_folder_path).await?;
566	        // Only Lidarr requires a metadata profile when adding an artist.
567	        let metadata = match service {
568	            ArrService::Lidarr => Some(self.metadata_profile_id().await?),
569	            _ => None,
570	        };
571	        let destination = (quality_profile_id, root.as_str());
572	        let body = service.add_body(candidate, destination, metadata, search_on_add, seasons)?;
573	        let path = format!("/{}", spec.resource);
574	        let added = self.write(service, Method::POST, &path, &body).await?;
575	        Ok(json!({
576	            "service": service,
577	            "item": lookup_item(&added, spec),
578	            "search_on_add": search_on_add,
579	            "seasons": seasons,
580	        }))
581	    }
