720	    /// Two-phase delete of one item, or of one Lidarr album while leaving its
721	    /// artist in place: preview with a bound confirmation, then execute.
722	    pub async fn delete_media(
723	        &self,
724	        service: ArrService,
725	        item_id: u32,
726	        delete_files: bool,
727	        confirmation: Option<&str>,
728	        album_id: Option<u32>,
729	    ) -> Result {
730	        let mut query = vec![("deleteFiles", delete_files.to_string())];
731	        let (path, mut outcome) = match album_id {
732	            Some(_) if service != ArrService::Lidarr => {
733	                return parameter("album_id is only supported for lidarr");
734	            }
735	            Some(album_id) => {
736	                let path = format!("/album/{album_id}");
737	                let request = self.request(service, Method::GET, &path)?;
738	                let album = self.record(request).await?;
739	                if album["artistId"].as_i64() != Some(item_id.into()) {
740	                    return parameter("album_id does not belong to item_id");
741	                }
742	                let artist = self.item(service, item_id).await?;
743	                let artist = json!({"id": item_id, "title": text(&artist["artistName"])});
744	                let album = summary(&album, "album_id", "title", album_id);
745	                (path, json!({"item": album, "artist": artist}))
746	            }
747	            None => {
748	                let item = self.item(service, item_id).await?;
749	                query.push(("addImportListExclusion", "false".to_owned()));
750	                (service.item_path(item_id), json!({"item": service.item_summary(&item, item_id)}))
751	            }
752	        };
753	        outcome["service"] = json!(service);
754	        outcome["delete_files"] = json!(delete_files);
755	        let action = json!([DELETE_ACTION, service, item_id, album_id, delete_files]).to_string();
756	        let now = Timestamp::now().as_second();
757	        if let Some(token) = confirmation {
758	            self.confirmation_must_match(&action, token, now)?;
759	            let request = self.request(service, Method::DELETE, &path)?.query(&query);
760	            self.fetch(request).await?;
761	            outcome["deleted"] = json!(true);
762	        } else {
763	            let expires = now.saturating_add_unsigned(self.settings.confirmation_ttl.as_secs());
764	            let token = format!("{expires}.{}", self.signature(expires, &action));
765	            outcome["confirmation_required"] = json!(true);
766	            outcome["confirmation"] = json!(token);
767	            outcome["confirmation_expires_at"] = json!(expires);
768	        }
769	        Ok(outcome)
770	    }
771	
772	    /// Hex HMAC-SHA256, keyed by the bearer token, over an expiry and action.
773	    fn signature(&self, expires: i64, action: &str) -> String {
774	        let key = self.settings.bearer_token.expose().as_bytes();
775	        let mut mac = Hmac::<Sha256>::new_from_slice(key).expect("HMAC takes any key length");
776	        mac.update(format!("{expires}.{action}").as_bytes());
777	        let mut hex = String::new();
778	        for byte in mac.finalize().into_bytes() {
779	            let _ = write!(hex, "{byte:02x}");
780	        }
781	        hex
782	    }
783	
784	    /// Require a fresh token signed for exactly this action's parameters.
785	    fn confirmation_must_match(&self, action: &str, token: &str, now: i64) -> Result<()> {
786	        let (expires, signature) = token.split_once('.').unwrap_or_default();
787	        let expires = expires.parse().unwrap_or(i64::MIN);
788	        let expected = self.signature(expires, action);
789	        if !bool::from(signature.as_bytes().ct_eq(expected.as_bytes())) {
790	            return parameter("confirmation is not valid for this action");
791	        }
792	        if now >= expires {
793	            return parameter("confirmation has expired; request a fresh preview");
794	        }
795	        Ok(())
796	    }
