798	    pub async fn history(
799	        &self,
800	        media_type: MediaType,
801	        start: Date,
802	        end: Date,
803	        page: u32,
804	        page_size: u32,
805	        user_id: Option<u32>,
806	    ) -> Result {
807	        date_range(start, end)?;
808	        let offset = u64::from(page - 1) * u64::from(page_size);
809	        let request = self
810	            .request(Service::Tautulli, Method::GET, "")?
811	            .query(&[("cmd", "get_history")])
812	            .query(&[("start", offset), ("length", page_size.into())])
813	            .query(&[("media_type", media_type)])
814	            // Tautulli's inclusive date bounds are named after/before.
815	            .query(&[("after", start), ("before", end)])
816	            // Discrete playback events, not grouped or activity-expanded rows.
817	            .query(&[("grouping", 0), ("include_activity", 0)])
818	            .query(&[("user_id", user_id)]);
819	        let payload = self.json(request).await?;
820	        let response = &payload["response"];
821	        if response["result"] != "success" {
822	            return upstream("upstream history request was not successful");
823	        }
824	        let rows: Vec<&Value> = match response["data"]["data"].as_array() {
825	            Some(rows) if rows.len() <= page_size as usize => {
826	                rows.iter().filter(|row| row.is_object()).collect()
827	            }
828	            _ => return upstream("upstream returned an unexpected history response"),
829	        };
830	        // Re-apply the requested filters locally so a misbehaving upstream
831	        // can never return another household member's rows.
832	        let kind = json!(media_type);
833	        let users = user_id.map(|user| [json!(user), json!(user.to_string())]);
834	        let mut items = Vec::new();
835	        for row in &rows {
836	            let other_type = row.get("media_type").is_some_and(|found| *found != kind);
837	            let other_user = users.as_ref().is_some_and(|users| !users.contains(&row["user_id"]));
838	            if other_type || other_user {
839	                continue;
840	            }
841	            let status = row["watched_status"].as_f64();
842	            let known = status.filter(|status| WATCHED_STATUSES.contains(status));
843	            // The source-prefixed identifiers are approved for household matching.
844	            items.push(json!({
845	                "media_type": media_type,
846	                "tautulli_user_id": id(&row["user_id"]),
847	                "user_name": text(&row["friendly_name"]),
848	                "tautulli_rating_key": id(&row["rating_key"]),
849	                "tautulli_history_id": id(&row["id"]),
850	                "title": text(&row["title"]),
851	                "parent_title": text(&row["parent_title"]),
852	                "grandparent_title": text(&row["grandparent_title"]),
853	                "played_at": row["started"].as_number(),
854	                "duration_seconds": row["duration"].as_number(),
855	                "completed": known.map(|status| status >= 1.0),
856	            }));
857	        }
858	        let received = offset + rows.len() as u64;
859	        let full_page = rows.len() == page_size as usize;
860	        // An upstream total smaller than what was already received is never trusted.
861	        let total = response["data"]["recordsFiltered"].as_u64();
862	        let total = total.filter(|total| *total >= received);
