956	    /// Log in to qBittorrent; the session id stays server-side only.
957	    ///
958	    /// The login answer carries the cookie in its headers, so it runs its own
959	    /// bounded exchange rather than [`MediaClient::fetch`].
960	    async fn qbit_login(&self) -> Result<String> {
961	        let Some(qbit) = self.settings.upstream(Service::Qbittorrent) else {
962	            return parameter("qbittorrent is not configured on this broker");
963	        };
964	        let Auth::Session { username, password } = &qbit.auth else {
965	            return parameter("qbittorrent is not configured on this broker");
966	        };
967	        let url = format!("{}{}/auth/login", qbit.base_url, Service::Qbittorrent.api_root());
968	        let form = [("username", username.as_str()), ("password", password.expose())];
969	        let body = url::form_urlencoded::Serializer::new(String::new()).extend_pairs(form).finish();
970	        if body.len() > MAX_REQUEST_BYTES {
971	            return parameter("qBittorrent credentials exceed the broker limit");
972	        }
973	        let request = self
974	            .http
975	            .request(Method::POST, url)
976	            .header(CONTENT_TYPE, "application/x-www-form-urlencoded")
977	            .body(body);
978	        let limit = self.settings.max_response_bytes;
979	        let attempt = async {
980	            let Ok(mut response) = request.send().await else {
981	                return upstream(FAILED);
982	            };
983	            let status = response.status().as_u16();
984	            let sid =
985	                response.headers().get_all(reqwest::header::SET_COOKIE).iter().find_map(|value| {
986	                    let value = value.to_str().ok()?;
987	                    let sid = value.strip_prefix("SID=")?.split(';').next()?;
988	                    valid_sid(sid).then(|| sid.to_owned())
989	                });
990	            if response.content_length().unwrap_or(0) > limit as u64 {
991	                return upstream(OVERSIZED);
992	            }
993	            let mut body = Vec::new();
994	            while let Some(chunk) = response.chunk().await.or_else(|_| upstream(FAILED))? {
995	                body.extend_from_slice(&chunk);
996	                if body.len() > limit {
997	                    return upstream(OVERSIZED);
998	                }
999	            }
1000	            Ok((status, sid, body))
1001	        };
1002	        let deadline = tokio::time::timeout(self.settings.timeout, attempt);
1003	        let (status, sid, body) =
1004	            deadline.await.unwrap_or_else(|_| upstream("upstream request timed out"))?;
1005	        let accepted = status < 300 && body.trim_ascii() == b"Ok.";
1006	        let Some(sid) = sid.filter(|_| accepted) else {
1007	            return upstream("upstream authentication failed");
1008	        };
1009	        *self.qbit_sid.lock().await = Some(sid.clone());
1010	        Ok(sid)
1011	    }
