1027	    /// One qBittorrent exchange, re-authenticating exactly once on a 403;
1028	    /// `build` completes the request afresh for each attempt.
1029	    async fn qbit_exchange(
1030	        &self,
1031	        method: Method,
1032	        path: &str,
1033	        build: impl Fn(RequestBuilder) -> RequestBuilder,
1034	    ) -> Result<Vec<u8>> {
1035	        for retried in [false, true] {
1036	            let cached = self.qbit_sid.lock().await.clone();
1037	            let sid = match cached {
1038	                Some(sid) => sid,
1039	                None => self.qbit_login().await?,
1040	            };
1041	            let request = self
1042	                .request(Service::Qbittorrent, method.clone(), path)?
1043	                .header(reqwest::header::COOKIE, format!("SID={sid}"));
1044	            let (status, body) = self.exchange(build(request)).await?;
1045	            if status == 403 && !retried {
1046	                *self.qbit_sid.lock().await = None;
1047	                continue;
1048	            }
1049	            if status >= 300 {
1050	                return upstream(format!("upstream returned HTTP {status}"));
1051	            }
1052	            return Ok(body);
1053	        }
1054	        upstream(FAILED)
1055	    }
