1111	    /// Report which requested info-hashes are present with complete data.
1112	    ///
1113	    /// Completeness is the client's recorded progress. Verifying bytes on
1114	    /// disk requires a recheck, which is a write and out of scope.
1115	    pub async fn torrent_check_paths(&self, hashes: &[String]) -> Result {
1116	        let mut normalized: Vec<String> = Vec::new();
1117	        for hash in hashes {
1118	            let hash = hash.trim().to_lowercase();
1119	            if !normalized.contains(&hash) {
1120	                normalized.push(hash);
1121	            }
1122	        }
1123	        if normalized.is_empty() || normalized.len() > MAX_HASHES {
1124	            return parameter("hashes must contain between 1 and 100 torrent hashes");
1125	        }
1126	        let valid = |hash: &str| {
1127	            matches!(hash.len(), 40 | 64) && hash.bytes().all(|byte| byte.is_ascii_hexdigit())
1128	        };
1129	        if normalized.iter().any(|hash| !valid(hash)) {
1130	            return parameter("torrent hashes must be 40 or 64 hexadecimal characters");
1131	        }
1132	        let query = [("hashes", normalized.join("|"))];
1133	        let rows = self.qbit_torrents(&query).await?;
1134	        let mut found: HashMap<String, &Value> = HashMap::new();
1135	        for row in &rows {
1136	            if let Some(hash) = text(&row["hash"]) {
1137	                let key = hash.to_lowercase();
1138	                if normalized.contains(&key) {
1139	                    found.insert(key, row);
1140	                }
1141	            }
1142	        }
1143	        let items: Vec<Value> = normalized
1144	            .iter()
1145	            .map(|hash| match found.get(hash) {
1146	                Some(row) => path_check_item(row),
1147	                None => json!({"hash": hash, "present": false}),
1148	            })
1149	            .collect();
1150	        Ok(json!({
1151	            "service": "qbittorrent",
1152	            "requested_count": normalized.len(),
1153	            "found_count": found.len(),
1154	            "items": items,
1155	        }))
1156	    }
