1202	    /// Add one metainfo file stopped, tagged, unchecked, and throttled, with
1203	    /// every client default that could move or reshape its files overridden.
1204	    async fn qbit_add(&self, metainfo: &[u8], hash: &str, save_path: &str) -> Result<()> {
1205	        let fields = [
1206	            ("savepath", save_path),
1207	            ("autoTMM", "false"),
1208	            ("useDownloadPath", "false"),
1209	            ("stopped", "true"),
1210	            ("stopCondition", "None"),
1211	            ("skip_checking", "false"),
1212	            ("contentLayout", "Original"),
1213	            ("tags", RESEED_TAG),
1214	            ("dlLimit", RESEED_DOWNLOAD_LIMIT),
1215	        ];
1216	        let mut boundary = format!("media-broker-{hash}");
1217	        while metainfo.windows(boundary.len()).any(|window| window == boundary.as_bytes()) {
1218	            boundary.push('-');
1219	        }
1220	        let mut body = Vec::with_capacity(metainfo.len() + 2048);
1221	        for (name, value) in fields {
1222	            let part = format!(
1223	                "--{boundary}\r\nContent-Disposition: form-data; name=\"{name}\"\r\n\r\n{value}\r\n"
1224	            );
1225	            body.extend_from_slice(part.as_bytes());
1226	        }
1227	        let file = format!(
1228	            "--{boundary}\r\nContent-Disposition: form-data; name=\"torrents\"; \
1229	             filename=\"{hash}.torrent\"\r\nContent-Type: application/x-bittorrent\r\n\r\n"
1230	        );
1231	        body.extend_from_slice(file.as_bytes());
1232	        body.extend_from_slice(metainfo);
1233	        body.extend_from_slice(format!("\r\n--{boundary}--\r\n").as_bytes());
1234	        let content_type = format!("multipart/form-data; boundary={boundary}");
1235	        let multipart = |request: RequestBuilder| {
1236	            request.header(CONTENT_TYPE, content_type.as_str()).body(body.clone())
1237	        };
1238	        let answer = self.qbit_exchange(Method::POST, "/torrents/add", multipart).await?;
1239	        // "Fails." covers duplicates and a client still starting up alike.
1240	        if answer.trim_ascii() != b"Ok." {
1241	            return upstream("upstream refused the torrent");
1242	        }
1243	        Ok(())
1244	    }
