1246	    /// Poll one torrent until it leaves every checking state. A settled state
1247	    /// counts only after a check was seen or `settled_after`, because the
1248	    /// state qBittorrent reports lags a recheck by up to one refresh interval.
1249	    /// `Err` carries the last row seen when the deadline passed first.
1250	    async fn await_check(
1251	        &self,
1252	        hash: &str,
1253	        mut seen_checking: bool,
1254	        settled_after: Instant,
1255	        deadline: Instant,
1256	    ) -> Result<std::result::Result<Value, Value>> {
1257	        loop {
1258	            let Some(row) = self.qbit_torrent(hash).await? else {
1259	                return upstream("the torrent disappeared from the client during its recheck");
1260	            };
1261	            if phase(&row) == Phase::Checking {
1262	                seen_checking = true;
1263	            } else if seen_checking || Instant::now() >= settled_after {
1264	                return Ok(Ok(row));
1265	            }
1266	            let poll = self.settings.reseed_poll_interval;
1267	            if Instant::now() + poll > deadline {
1268	                return Ok(Err(row));
1269	            }
1270	            tokio::time::sleep(poll).await;
1271	        }
1272	    }
