1274	    /// Re-add one v1 metainfo file over data already on disk and start seeding
1275	    /// only once a full recheck verifies every piece; otherwise remove it
1276	    /// again, keeping the data. Torrents this tool did not add are never
1277	    /// touched, so a whole batch can be replayed after any interruption.
1278	    pub async fn torrent_reseed(&self, torrent_b64: &str, save_path: Option<&str>) -> Result {
1279	        let Ok(metainfo) = BASE64.decode(torrent_b64.trim()) else {
1280	            return parameter("torrent_b64 must be standard base64");
1281	        };
1282	        if metainfo.len() > MAX_TORRENT_BYTES {
1283	            return parameter("torrent_b64 decodes to more than the 1 MiB metainfo limit");
1284	        }
1285	        let Some(hash) = info_hash(&metainfo) else {
1286	            return parameter(
1287	                "torrent_b64 must hold one well-formed v1 metainfo file; v2 and hybrid \
1288	                 torrents are not supported",
1289	            );
1290	        };
1291	        let save_path = self.reseed_save_path(save_path)?;
1292	        let _serial = self.reseed.lock().await;
1293	        let outcome = |outcome: &str, row: &Value| reseed_item(&hash, outcome, row);
1294	        let present = self.qbit_torrent(&hash).await?;
1295	        if let Some(row) = present.as_ref().filter(|row| !tagged(row)) {
1296	            return Ok(outcome("already_present", row));
1297	        }
1298	        let settle = self.reseed_preflight().await?;
1299	        let deadline = Instant::now() + self.settings.reseed_deadline;
1300	        let fresh = present.is_none();
1301	        let row = if let Some(row) = present {
1302	            row
1303	        } else {
1304	            self.qbit_add(&metainfo, &hash, save_path).await?;
1305	            // The add is asynchronous: the torrent is listed only once
1306	            // libtorrent has loaded it.
1307	            self.await_listed(&hash, deadline).await?
1308	        };
1309	        let checked = match phase(&row) {
1310	            Phase::Seeding if complete(&row) => return Ok(outcome("reseeding", &row)),
1311	            Phase::Seeding | Phase::Downloading => row,
1312	            Phase::Checking => match self.await_check(&hash, true, Instant::now(), deadline).await?
1313	            {
1314	                Ok(row) => row,
1315	                Err(last) => return Ok(outcome("checking", &last)),
1316	            },
1317	            // A stopped torrent from an earlier call was verified only if it
1318	            // is complete: nothing but a recheck raises its progress.
1319	            Phase::Settled if complete(&row) && !fresh => row,
1320	            Phase::Settled => {
1321	                self.qbit_post("/torrents/recheck", &[("hashes", &hash)]).await?;
1322	                let settled_after = Instant::now() + settle;
1323	                match self.await_check(&hash, false, settled_after, deadline).await? {
1324	                    Ok(row) => row,
1325	                    Err(last) => return Ok(outcome("checking", &last)),
1326	                }
1327	            }
1328	        };
1329	        if complete(&checked) {
1330	            if phase(&checked) != Phase::Seeding {
1331	                self.qbit_post("/torrents/start", &[("hashes", &hash)]).await?;
1332	            }
1333	            return Ok(outcome("reseeding", &checked));
1334	        }
1335	        let form = [("hashes", hash.as_str()), ("deleteFiles", "false")];
1336	        self.qbit_post("/torrents/delete", &form).await?;
1337	        Ok(outcome("aborted_incomplete", &checked))
1338	    }
