1340	    /// Wait for a just-added torrent to be listed.
1341	    async fn await_listed(&self, hash: &str, deadline: Instant) -> Result {
1342	        loop {
1343	            if let Some(row) = self.qbit_torrent(hash).await? {
1344	                return Ok(row);
1345	            }
1346	            let poll = self.settings.reseed_poll_interval;
1347	            if Instant::now() + poll > deadline {
1348	                return upstream("the added torrent was not listed before the deadline");
1349	            }
1350	            tokio::time::sleep(poll).await;
1351	        }
1352	    }
1353	}
1354	
1355	/// qBittorrent session ids are short ASCII tokens; anything else is untrusted.
1356	fn valid_sid(sid: &str) -> bool {
1357	    let token = sid.bytes().all(|byte| byte.is_ascii_alphanumeric() || b"-._~".contains(&byte));
1358	    !sid.is_empty() && sid.len() <= 256 && token
1359	}
1360	
1361	/// Project one torrent row to its allow-listed swarm fields.
1362	fn torrent_item(row: &Value) -> Value {
1363	    json!({
1364	        "hash": text(&row["hash"]),
1365	        "name": text(&row["name"]),
1366	        "state": text(&row["state"]),
1367	        "size_bytes": row["size"].as_i64(),
1368	        "progress": row["progress"].as_number(),
1369	        "ratio": row["ratio"].as_number(),
1370	        "seeding_time_seconds": row["seeding_time"].as_i64(),
1371	        "save_path": text(&row["save_path"]),
1372	        "added_on": row["added_on"].as_i64(),
1373	        "amount_left_bytes": row["amount_left"].as_i64(),
1374	    })
1375	}
1376	
1377	/// Project one torrent row for the reseed-candidate audit.
1378	fn path_check_item(row: &Value) -> Value {
1379	    let progress = row["progress"].as_f64();
1380	    json!({
1381	        "hash": text(&row["hash"]),
1382	        "present": true,
1383	        "name": text(&row["name"]),
1384	        "state": text(&row["state"]),
1385	        "progress": row["progress"].as_number(),
1386	        "amount_left_bytes": row["amount_left"].as_i64(),
1387	        "save_path": text(&row["save_path"]),
1388	        "data_complete": progress.map(|progress| progress >= 1.0),
1389	    })
1390	}
1391	
1392	/// Where a torrent stands for a reseed, from qBittorrent 5.1's state string.
1393	#[derive(Clone, Copy, PartialEq, Eq)]
1394	enum Phase {
1395	    /// Hashing, queued for a check slot, or moving storage.
1396	    Checking,
1397	    /// Running with the client's recorded data complete.
1398	    Seeding,
1399	    /// Running while incomplete: removed at once, never left to download.
1400	    Downloading,
1401	    /// Stopped, errored, missing files, or unknown.
1402	    Settled,
1403	}
1404	
1405	fn phase(row: &Value) -> Phase {
1406	    match row["state"].as_str().unwrap_or_default() {
1407	        "checkingUP" | "checkingDL" | "checkingResumeData" | "moving" => Phase::Checking,
1408	        "uploading" | "stalledUP" | "queuedUP" | "forcedUP" => Phase::Seeding,
1409	        "downloading" | "stalledDL" | "queuedDL" | "forcedDL" | "metaDL" | "forcedMetaDL" => {
1410	            Phase::Downloading
1411	        }
1412	        _ => Phase::Settled,
1413	    }
1414	}
1415	
1416	/// Every piece of every file verified: full progress, nothing left, and no
1417	/// file excluded from the wanted size.
1418	fn complete(row: &Value) -> bool {
1419	    let size = row["size"].as_i64();
1420	    row["progress"].as_f64().is_some_and(|progress| progress >= 1.0)
1421	        && row["amount_left"].as_i64() == Some(0)
1422	        && size.is_some_and(|size| size > 0)
1423	        && size == row["total_size"].as_i64()
1424	}
1425	
1426	/// Whether this broker added the torrent; qBittorrent joins tags with ", ".
1427	fn tagged(row: &Value) -> bool {
1428	    text(&row["tags"]).is_some_and(|tags| tags.split(',').any(|tag| tag.trim() == RESEED_TAG))
1429	}
1430	
1431	/// Project one reseed outcome with the fields a batch report needs.
1432	fn reseed_item(hash: &str, outcome: &str, row: &Value) -> Value {
1433	    json!({
1434	        "service": "qbittorrent",
1435	        "hash": hash,
1436	        "outcome": outcome,
1437	        "name": text(&row["name"]),
1438	        "state": text(&row["state"]),
1439	        "progress": row["progress"].as_number(),
1440	        "size_bytes": row["total_size"].as_i64(),
1441	        "amount_left_bytes": row["amount_left"].as_i64(),
1442	        "save_path": text(&row["save_path"]),
1443	    })
1444	}
1445	
1446	/// The end offset of the bencoded value starting at `at`, or `None` when it
1447	/// is malformed, truncated, or nested deeper than [`MAX_BENCODE_DEPTH`].
1448	fn bencode_end(data: &[u8], at: usize, depth: usize) -> Option<usize> {
1449	    match *data.get(at)? {
1450	        b'i' => {
1451	            let end = at + 1 + data.get(at + 1..)?.iter().position(|&byte| byte == b'e')?;
1452	            let digits = data[at + 1..end].strip_prefix(b"-").unwrap_or(&data[at + 1..end]);
1453	            let valid = !digits.is_empty() && digits.iter().all(u8::is_ascii_digit);
1454	            valid.then_some(end + 1)
1455	        }
1456	        b'l' | b'd' if depth < MAX_BENCODE_DEPTH => {
1457	            let dictionary = data[at] == b'd';
1458	            let mut next = at + 1;
1459	            while *data.get(next)? != b'e' {
1460	                // Dictionary keys are byte strings, each followed by its value.
1461	                if dictionary {
1462	                    data[next].is_ascii_digit().then_some(())?;
1463	                    next = bencode_end(data, next, depth + 1)?;
1464	                }
1465	                next = bencode_end(data, next, depth + 1)?;
1466	            }
1467	            Some(next + 1)
1468	        }
1469	        b'0'..=b'9' => {
1470	            let colon = at + data[at..].iter().position(|&byte| byte == b':')?;
1471	            let length: usize = std::str::from_utf8(&data[at..colon]).ok()?.parse().ok()?;
1472	            let end = colon.checked_add(1)?.checked_add(length)?;
1473	            (end <= data.len()).then_some(end)
1474	        }
1475	        _ => None,
1476	    }
1477	}
1478	
1479	/// One dictionary entry: the raw key and the byte range of its value.
1480	type Entry<'a> = (&'a [u8], Range<usize>);
1481	
1482	/// The entries of the bencoded dictionary starting at `at`, plus the
1483	/// dictionary's end offset.
1484	fn bencode_entries(data: &[u8], at: usize) -> Option<(Vec<Entry<'_>>, usize)> {
1485	    (*data.get(at)? == b'd').then_some(())?;
1486	    let mut entries = Vec::new();
1487	    let mut next = at + 1;
1488	    while *data.get(next)? != b'e' {
1489	        let key_end = data[next].is_ascii_digit().then(|| bencode_end(data, next, 1))??;
1490	        let colon = next + data[next..key_end].iter().position(|&byte| byte == b':')?;
1491	        let value_end = bencode_end(data, key_end, 1)?;
1492	        entries.push((&data[colon + 1..key_end], key_end..value_end));
1493	        next = value_end;
1494	    }
1495	    Some((entries, next + 1))
1496	}
1497	
1498	/// The lowercase hex v1 info-hash of one metainfo file: SHA-1 over the exact
1499	/// bytes of its `info` dictionary, which must carry v1 `pieces`. Anything but
1500	/// a single well-formed top-level dictionary is refused.
1501	fn info_hash(metainfo: &[u8]) -> Option<String> {
1502	    let (entries, end) = bencode_entries(metainfo, 0)?;
1503	    (end == metainfo.len()).then_some(())?;
1504	    let (_, info) = entries.into_iter().find(|(key, _)| *key == b"info")?;
1505	    let (fields, _) = bencode_entries(metainfo, info.start)?;
1506	    // qBittorrent identifies v2 and hybrid torrents by their truncated v2
1507	    // hash, so only pure v1 metainfo has an id this function can compute.
1508	    let has = |name: &[u8]| fields.iter().any(|(key, _)| *key == name);
1509	    (has(b"pieces") && !has(b"meta version")).then_some(())?;
1510	    let mut hex = String::with_capacity(40);
1511	    for byte in Sha1::digest(&metainfo[info]) {
1512	        let _ = write!(hex, "{byte:02x}");
1513	    }
1514	    Some(hex)
1515	}
1516

