1	//! The gated qBittorrent reseed: verified-complete starts, kept-data removals,
2	//! untouched foreign torrents, and replay of interrupted work.
3	
4	mod common;
5	
6	use std::{
7	    collections::HashMap,
8	    sync::{Arc, Mutex},
9	};
