11	use axum::{body::Body, response::Response};
12	use base64::{Engine, engine::general_purpose::STANDARD as BASE64};
13	use common::{Broker, QBIT_SID, RESEED_TOOL, Seen, respond, with, with_qbit};
14	use media_broker::config::Settings;
15	use serde_json::{Value, json};
16	use sha1::{Digest, Sha1};
17	
18	const SAVE_PATH: &str = "/data/torrents/music";
19	const TAG: &str = "media-broker-reseed";
20	
21	/// A v1 metainfo file whose info dictionary carries `extra` before `pieces`.
22	fn metainfo(extra: &str) -> (Vec<u8>, String) {
23	    let info = format!(
24	        "d6:lengthi32768e4:name5:Album12:piece lengthi16384e{extra}6:pieces40:{}e",
25	        "p".repeat(40)
26	    );
27	    let digest = Sha1::digest(info.as_bytes());
28	    let hash = digest.iter().fold(String::new(), |hex, byte| hex + &format!("{byte:02x}"));
29	    let file = format!("d8:announce22:https://tracker.test/a4:info{info}e");
30	    (file.into_bytes(), hash)
31	}
32	
33	fn arguments(file: &[u8]) -> Value {
34	    json!({"torrent_b64": BASE64.encode(file)})
35	}
36	
37	fn preferences() -> Value {
38	    json!({"incomplete_files_ext": false, "excluded_file_names_enabled": false,
39	           "use_unwanted_folder": false, "refresh_interval": 0, "proxy_password": "REDACTED"})
40	}
41	
42	/// One torrent row as qBittorrent 5.1 lists it.
43	fn row(hash: &str, state: &str, progress: f64, tags: &str) -> Value {
44	    let left = if progress >= 1.0 { 0 } else { 16384 };
45	    json!({"hash": hash, "name": "Album", "state": state, "progress": progress,
46	           "amount_left": left, "size": 32768, "total_size": 32768,
47	           "save_path": SAVE_PATH, "tags": tags, "tracker": "REDACTED"})
48	}
49	
50	/// A stateful fake qBittorrent. The first info poll after an add still
51	/// misses the torrent, the first poll after a recheck reports the stale
52	/// pre-check state, then `checks` polls report checking before `after` holds.
53	#[derive(Clone)]
54	struct Client {
55	    torrent: Arc<Mutex<Option<Value>>>,
56	    script: Arc<Mutex<Vec<Value>>>,
57	    after: Value,
58	    checks: usize,
59	    preferences: Value,
60	    add_answer: &'static str,
61	    /// Fields of the torrent as first listed after an add.
62	    added: Value,
63	}
64	
65	impl Client {
66	    fn new(present: Option<Value>, after: Value) -> Self {
67	        Self {
68	            torrent: Arc::new(Mutex::new(present)),
69	            script: Arc::new(Mutex::new(Vec::new())),
70	            after,
71	            checks: 2,
72	            preferences: preferences(),
73	            add_answer: "Ok.",
74	            added: json!({}),
75	        }
76	    }
77	
78	    fn backend(self) -> impl Fn(&Seen) -> Response + Send + Sync + 'static {
79	        let pending_add: Arc<Mutex<Option<Value>>> = Arc::default();
80	        move |seen| {
81	            if seen.path == "/api/v2/auth/login" {
82	                let cookie = format!("SID={QBIT_SID}");
83	                return Response::builder()
84	                    .header("set-cookie", cookie)
85	                    .body(Body::from("Ok."))
86	                    .unwrap();
87	            }
88	            let mut torrent = self.torrent.lock().unwrap();
89	            let mut script = self.script.lock().unwrap();
90	            let hash = |seen: &Seen| {
91	                let form: HashMap<String, String> =
92	                    url::form_urlencoded::parse(seen.text.as_bytes()).into_owned().collect();
93	                form.get("hashes").cloned().unwrap_or_default()
94	            };
95	            match (seen.method.as_str(), seen.path.as_str()) {
96	                ("GET", "/api/v2/app/preferences") => respond(200, self.preferences.to_string()),
97	                ("GET", "/api/v2/torrents/info") => {
98	                    if let Some(added) = pending_add.lock().unwrap().take() {
99	                        *torrent = Some(added);
100	                        return respond(200, "[]");
101	                    }
102	                    if !script.is_empty() {
103	                        let next = script.remove(0);
104	                        *torrent = Some(with(torrent.clone().unwrap(), next));
105	                    }
106	                    let rows: Vec<Value> = torrent.iter().cloned().collect();
107	                    respond(200, Value::from(rows).to_string())
108	                }
109	                ("POST", "/api/v2/torrents/add") => {
110	                    let (_, info_hash) = metainfo("");
111	                    let added = with(row(&info_hash, "stoppedDL", 0.0, TAG), self.added.clone());
112	                    *pending_add.lock().unwrap() = Some(added);
113	                    respond(200, self.add_answer)
114	                }
115	                ("POST", "/api/v2/torrents/recheck") => {
116	                    assert_eq!(hash(seen), torrent.as_ref().unwrap()["hash"]);
117	                    // The stale pre-check state is reported once, then checking.
118	                    let stale = torrent.clone().unwrap();
119	                    script.push(json!({"state": stale["state"]}));
120	                    for _ in 0..self.checks {
121	                        script.push(json!({"state": "checkingDL", "progress": 0.5}));
122	                    }
123	                    script.push(self.after.clone());
124	                    respond(200, Body::empty())
125	                }
126	                ("POST", "/api/v2/torrents/start") => {
127	                    assert_eq!(hash(seen), torrent.as_ref().unwrap()["hash"]);
128	                    let started = with(torrent.clone().unwrap(), json!({"state": "stalledUP"}));
129	                    *torrent = Some(started);
130	                    respond(200, Body::empty())
131	                }
132	                ("POST", "/api/v2/torrents/delete") => {
133	                    assert_eq!(hash(seen), torrent.as_ref().unwrap()["hash"]);
134	                    *torrent = None;
135	                    respond(200, Body::empty())
136	                }
137	                _ => respond(404, Body::empty()),
138	            }
139	        }
140	    }
141	}
