164	/// The qBittorrent actions posted so far, in order.
165	fn actions(broker: &Broker) -> Vec<String> {
166	    let seen = broker.seen();
167	    let posts = seen.iter().filter(|request| request.method == "POST");
168	    let actions = posts.filter_map(|request| request.path.strip_prefix("/api/v2/torrents/"));
