172	/// The named text fields of one multipart body.
173	fn multipart_fields(body: &str) -> HashMap<String, String> {
174	    let parts = body.split("\r\n--").filter_map(|part| {
175	        let (headers, value) = part.split_once("\r\n\r\n")?;
176	        let name = headers.split("name=\"").nth(1)?.split('"').next()?;
177	        (!headers.contains("filename=")).then(|| (name.to_owned(), value.to_owned()))
178	    });
179	    parts.collect()
180	}
