87	impl Broker {
88	    /// A broker with default settings whose five upstreams all reach `upstream`.
89	    pub async fn start(upstream: impl Fn(&Seen) -> Response + Send + Sync + 'static) -> Self {
90	        Self::configured(|_| {}, upstream).await
91	    }
