98	    pub async fn configured(
99	        configure: impl FnOnce(&mut Settings),
100	        upstream: impl Fn(&Seen) -> Response + Send + Sync + 'static,
101	    ) -> Self {
102	        let seen = Arc::new(Mutex::new(Vec::new()));
103	        let log = Arc::clone(&seen);
104	        let upstream = Arc::new(upstream);
105	        let fake = Router::new().fallback(move |request: Request| {
106	            let (log, upstream) = (Arc::clone(&log), Arc::clone(&upstream));
107	            async move {
108	                let (parts, body) = request.into_parts();
109	                let body = to_bytes(body, usize::MAX).await.unwrap();
110	                let query = parts.uri.query().unwrap_or_default();
111	                let record = Seen {
112	                    method: parts.method.to_string(),
113	                    path: parts.uri.path().to_owned(),
114	                    query: url::form_urlencoded::parse(query.as_bytes()).into_owned().collect(),
115	                    target: parts.uri.to_string(),
116	                    headers: parts.headers,
117	                    body: serde_json::from_slice(&body).unwrap_or(Value::Null),
118	                    text: String::from_utf8_lossy(&body).into_owned(),
119	                };
120	                let response = upstream(&record);
121	                log.lock().unwrap().push(record);
122	                response
123	            }
124	        });
125	        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
126	        let base_url = format!("http://{}", listener.local_addr().unwrap());
127	        tokio::spawn(async move { axum::serve(listener, fake).await.unwrap() });
