131	            upstreams: Service::ALL.map(|service| {
132	                (service != Service::Qbittorrent).then(|| Upstream {
133	                    base_url: base_url.clone(),
134	                    auth: Auth::Key(Secret::new(format!("{}-key", service.name()))),
135	                })
136	            }),
