160	    pub async fn send(&self, request: Request) -> Reply {
161	        let response = self.app.clone().oneshot(request).await.unwrap();
162	        let (parts, body) = response.into_parts();
163	        let body = to_bytes(body, usize::MAX).await.unwrap();
